function validate([flips]) {
  if (!Array.isArray(flips) || flips.length < 1 || flips.length > 50000) return 'flips needs 1 to 50000 values.';
  const n = flips.length;
  const seen = new Array(n + 1).fill(false);
  for (const v of flips) {
    if (!Number.isInteger(v) || v < 1 || v > n) return 'Every value must be between 1 and n.';
    if (seen[v]) return 'flips must be a permutation of 1..n (no repeats).';
    seen[v] = true;
  }
  return null;
}

