function numTimesAllBlue(flips) {
  let flippedSum = 0;
  let count = 0;
  for (let step = 1; step <= flips.length; step++) {
    flippedSum += flips[step - 1];
    const alignedSum = step * (step + 1) / 2;
    if (flippedSum === alignedSum) {
      count++;
    }
  }
  return count;
}

