function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 8);
  const flips = Array.from({ length: n }, (_, i) => i + 1);
  const shuffle = (from, to) => {
    for (let i = to - 1; i > from; i--) {
      const j = from + Math.floor(rand() * (i - from + 1));
      [flips[i], flips[j]] = [flips[j], flips[i]];
    }
  };
  if (rand() < 0.4) {
    shuffle(0, n);
  } else {
    // Shuffle inside consecutive blocks so several steps end up aligned.
    const maxBlock = size === 'large' ? 60 : 3;
    let start = 0;
    while (start < n) {
      const end = Math.min(n, start + 1 + Math.floor(rand() * maxBlock));
      shuffle(start, end);
      start = end;
    }
  }
  return [flips];
}
